pub fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of rows in the input matrix
    let rows = x.len();
    // Number of columns in the input matrix (all rows have the same length)
    let cols = x[0].len();

    // Prepare the output matrix with `cols` rows,
    // each of which will have capacity for `rows` elements.
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(cols);
    for c in 0..cols {
        let mut new_row: Vec<f32> = Vec::with_capacity(rows);
        for r in 0..rows {
            new_row.push(x[r][c]);
        }
        result.push(new_row);
    }

    result
}

